//! TODO business operations backed by PostgreSQL.
use chrono::{DateTime, Utc};
use postgres::{Client, NoTls, Row};
use std::{env, fmt, time::Duration};

pub const DEFAULT_DATABASE_URL: &str = "postgres://todo:todo@127.0.0.1:5432/todo";

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum Status {
    Completed,
    New,
    Deleted,
}

#[derive(Debug, Clone, PartialEq, Eq)]
pub struct Task {
    pub id: i32,
    pub description: String,
    pub added: DateTime<Utc>,
    pub update: DateTime<Utc>,
    pub status: Status,
}

#[derive(Debug)]
pub enum Error {
    Database(postgres::Error),
    Configuration(env::VarError),
    NotFound(i32),
    InvalidStatus(String),
    IncompatibleSchema,
}

impl fmt::Display for Error {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            Self::Database(error) => match error.as_db_error() {
                Some(detail) => write!(f, "database: {}", detail.message()),
                None => write!(f, "database: {error}"),
            },
            Self::Configuration(error) => write!(f, "database configuration: {error}"),
            Self::NotFound(id) => write!(f, "task {id} does not exist"),
            Self::IncompatibleSchema => write!(f, "database: incompatible tasks schema"),
            Self::InvalidStatus(status) => write!(f, "database: unsupported task status {status}"),
        }
    }
}

impl std::error::Error for Error {
    fn source(&self) -> Option<&(dyn std::error::Error + 'static)> {
        match self {
            Self::Database(error) => Some(error),
            Self::Configuration(error) => Some(error),
            _ => None,
        }
    }
}

impl From<postgres::Error> for Error {
    fn from(error: postgres::Error) -> Self {
        Self::Database(error)
    }
}

fn task(row: Row) -> Result<Task, Error> {
    let status: String = row.try_get("status")?;
    let status = match status.as_str() {
        "New" => Status::New,
        "Completed" => Status::Completed,
        "Deleted" => Status::Deleted,
        _ => return Err(Error::InvalidStatus(status)),
    };
    Ok(Task {
        id: row.try_get("id")?,
        description: row.try_get("description")?,
        added: row.try_get("added")?,
        update: row.try_get("update")?,
        status,
    })
}

/// Owns a live database connection; each mutation commits before returning.
pub struct TodoStore {
    client: Client,
}

impl TodoStore {
    /// DATABASE_URL or the local compose database, independent of working directory.
    pub fn project() -> Result<Self, Error> {
        let url = match env::var("DATABASE_URL") {
            Ok(url) => url,
            Err(env::VarError::NotPresent) => DEFAULT_DATABASE_URL.to_owned(),
            Err(error) => return Err(Error::Configuration(error)),
        };
        Self::connect(&url)
    }

    /// Connect with a five-second connection timeout and initialize a fresh schema.
    pub fn connect(url: &str) -> Result<Self, Error> {
        let mut config: postgres::Config = url.parse()?;
        config.connect_timeout(Duration::from_secs(5));
        let mut client = config.connect(NoTls)?;
        client.simple_query("SELECT 1")?;
        let mut transaction = client.transaction()?;
        transaction.batch_execute(
            "DO $$ BEGIN
                IF NOT EXISTS (SELECT 1 FROM pg_type WHERE typname = 'task_status'
                               AND typnamespace = current_schema()::regnamespace) THEN
                    CREATE TYPE task_status AS ENUM ('Completed', 'New', 'Deleted');
                END IF;
             END $$;
             CREATE TABLE IF NOT EXISTS tasks (
                id integer GENERATED ALWAYS AS IDENTITY PRIMARY KEY CHECK (id > 0),
                description text NOT NULL,
                added timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP,
                \"update\" timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP,
                status task_status NOT NULL DEFAULT 'New'
             );",
        )?;
        // CREATE TABLE IF NOT EXISTS alone would silently accept incompatible tables.
        let compatible: bool = transaction
            .query_one(
                "SELECT COALESCE(
                (SELECT count(*) = 5 AND bool_and(attnotnull AND COALESCE(atttypid =
                    CASE attname
                        WHEN 'id' THEN 'integer'::regtype
                        WHEN 'description' THEN 'text'::regtype
                        WHEN 'added' THEN 'timestamptz'::regtype
                        WHEN 'update' THEN 'timestamptz'::regtype
                        WHEN 'status' THEN 'task_status'::regtype
                    END, false))
                 FROM pg_attribute WHERE attrelid = 'tasks'::regclass
                 AND attnum > 0 AND NOT attisdropped)
                AND EXISTS (SELECT 1 FROM pg_constraint c JOIN pg_attribute a
                    ON a.attrelid = c.conrelid AND a.attname = 'id'
                    WHERE c.conrelid = 'tasks'::regclass AND c.contype = 'p'
                    AND c.conkey = ARRAY[a.attnum] AND a.attidentity IN ('a', 'd'))
                AND (SELECT array_agg(enumlabel ORDER BY enumlabel) =
                    ARRAY['Completed', 'Deleted', 'New']::name[]
                    FROM pg_enum WHERE enumtypid = 'task_status'::regtype), false)",
                &[],
            )?
            .get(0);
        if !compatible {
            return Err(Error::IncompatibleSchema);
        }
        transaction.commit()?;
        Ok(Self { client })
    }

    /// Visible tasks in creation order; Deleted rows remain only in the database.
    pub fn list(&mut self) -> Result<Vec<Task>, Error> {
        self.client
            .query("SELECT id, description, added, \"update\", status::text FROM tasks WHERE status <> 'Deleted' ORDER BY id", &[])?
            .into_iter().map(task).collect()
    }

    pub fn create(&mut self, description: impl Into<String>) -> Result<Task, Error> {
        task(self.client.query_one(
            "INSERT INTO tasks (description, added, \"update\", status) VALUES ($1, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, 'New') RETURNING id, description, added, \"update\", status::text",
            &[&description.into()],
        )?)
    }

    /// Already-completed tasks retain all timestamps and succeed unchanged.
    pub fn complete(&mut self, id: i32) -> Result<Task, Error> {
        let mut transaction = self.client.transaction()?;
        let row = transaction.query_opt(
            "SELECT id, description, added, \"update\", status::text FROM tasks WHERE id = $1 AND status <> 'Deleted' FOR UPDATE",
            &[&id],
        )?.ok_or(Error::NotFound(id))?;
        let current = task(row)?;
        let result = if current.status == Status::New {
            task(transaction.query_one(
                "UPDATE tasks SET status = 'Completed', \"update\" = clock_timestamp() WHERE id = $1 RETURNING id, description, added, \"update\", status::text",
                &[&id],
            )?)?
        } else {
            current
        };
        transaction.commit()?;
        Ok(result)
    }

    /// Soft-delete a visible task, retaining its identity and creation timestamp.
    pub fn delete(&mut self, id: i32) -> Result<Task, Error> {
        let row = self.client.query_opt(
            "UPDATE tasks SET status = 'Deleted', \"update\" = clock_timestamp() WHERE id = $1 AND status <> 'Deleted' RETURNING id, description, added, \"update\", status::text",
            &[&id],
        )?.ok_or(Error::NotFound(id))?;
        task(row)
    }
}
use std::{env, process::ExitCode};
use todolist_rust::{Error, Status, TodoStore};

const HELP: &str = "TODO commands:
  add <description>  Add one task; quote descriptions: add \"Buy milk\"
  delete <id>        Delete a task
  complete <id>      Mark a task complete
  list               List tasks: [ ] incomplete, [x] complete
  help               Show this help (also -h, --help, or no arguments)

Storage: PostgreSQL must be alive for every invocation. Configure DATABASE_URL.
IDs are decimal integers from 0 to 2147483647 (stored IDs start at 1). Empty descriptions are allowed: add \"\".";

enum Command {
    Add(String),
    Delete(i32),
    Complete(i32),
    List,
    Help,
}

fn parse(args: Vec<String>) -> Result<Command, &'static str> {
    let id = |value: &str| {
        if value.is_empty() || !value.bytes().all(|byte| byte.is_ascii_digit()) {
            return Err("ID must be an unsigned decimal integer");
        }
        value
            .parse()
            .map_err(|_| "ID is too large for PostgreSQL integer")
    };
    match args.as_slice() {
        [] => Ok(Command::Help),
        [command] if matches!(command.as_str(), "help" | "-h" | "--help") => Ok(Command::Help),
        [command] if command == "list" => Ok(Command::List),
        [command, description] if command == "add" => Ok(Command::Add(description.clone())),
        [command, value] if command == "delete" => Ok(Command::Delete(id(value)?)),
        [command, value] if command == "complete" => Ok(Command::Complete(id(value)?)),
        _ => Err("unknown command or incorrect number of arguments"),
    }
}

fn execute(command: Command, store: &mut TodoStore) -> Result<(), Error> {
    match command {
        Command::Help => println!("{HELP}"),
        Command::Add(description) => println!("Added task {}", store.create(description)?.id),
        Command::Delete(id) => println!("Deleted task {}", store.delete(id)?.id),
        Command::Complete(id) => println!("Completed task {}", store.complete(id)?.id),
        Command::List => {
            let tasks = store.list()?;
            if tasks.is_empty() {
                println!("No tasks.");
            }
            for task in tasks {
                let marker = if task.status == Status::Completed {
                    'x'
                } else {
                    ' '
                };
                println!("{} [{marker}] {}", task.id, task.description);
            }
        }
    }
    Ok(())
}

fn main() -> ExitCode {
    let mut store = match TodoStore::project() {
        Ok(store) => store,
        Err(error) => {
            eprintln!("{error}");
            return ExitCode::from(1);
        }
    };
    let command = env::args_os()
        .skip(1)
        .map(|arg| arg.into_string().map_err(|_| "arguments must be UTF-8"))
        .collect::<Result<Vec<_>, _>>()
        .and_then(parse);
    match command {
        Err(error) => {
            eprintln!("{error}. Run 'todolist_rust help' for usage.");
            ExitCode::from(2)
        }
        Ok(command) => match execute(command, &mut store) {
            Ok(()) => ExitCode::SUCCESS,
            Err(error) => {
                eprintln!("{error}");
                ExitCode::from(1)
            }
        },
    }
}
//! Run only against a fresh disposable database selected by DATABASE_URL.
use todolist_rust::{Status, TodoStore};

fn main() -> Result<(), Box<dyn std::error::Error>> {
    let mut store = TodoStore::project()?;
    assert!(store.list()?.is_empty());
    let a = store.create("A")?;
    let b = store.create("B")?;
    assert_eq!(store.list()?, vec![a.clone(), b.clone()]);
    let completed = store.complete(a.id)?;
    assert_eq!(completed.status, Status::Completed);
    assert_eq!(store.complete(a.id)?, completed);
    store.delete(b.id)?;
    assert_eq!(TodoStore::project()?.list()?, vec![completed.clone()]);
    store.delete(completed.id)?;
    assert!(TodoStore::project()?.list()?.is_empty());
    println!("PASS: PostgreSQL lifecycle, including fresh connection and soft deletion");
    Ok(())
}
use chrono::Utc;
use todolist_rust::{Error, Status, TodoStore};

// The process runner provisions a separate real database for this API contract.
#[test]
fn public_api_state_and_connection_lifetime() -> Result<(), Box<dyn std::error::Error>> {
    let url = std::env::var("DATABASE_URL").expect("run tests/cli_e2e.py for an isolated database");
    let mut store = TodoStore::connect(&url)?;
    assert!(store.list()?.is_empty());
    let before = Utc::now();
    let created = store.create("API task")?;
    assert_eq!(created.id, 1);
    assert_eq!(created.description, "API task");
    assert_eq!(created.status, Status::New);
    assert_eq!(created.added, created.update);
    assert!(created.added >= before && created.added <= Utc::now());
    drop(store);
    let mut reconnected = TodoStore::connect(&url)?;
    assert_eq!(reconnected.list()?, vec![created.clone()]);
    let completed = reconnected.complete(created.id)?;
    assert_eq!(completed.status, Status::Completed);
    assert_eq!(completed.added, created.added);
    assert_eq!(reconnected.complete(created.id)?, completed);
    let deleted = reconnected.delete(created.id)?;
    assert_eq!(deleted.status, Status::Deleted);
    assert_eq!(deleted.description, created.description);
    assert_eq!(deleted.added, created.added);
    assert!(reconnected.list()?.is_empty());
    assert!(matches!(
        reconnected.complete(created.id),
        Err(Error::NotFound(1))
    ));
    assert!(matches!(
        reconnected.delete(created.id),
        Err(Error::NotFound(1))
    ));
    assert!(matches!(
        reconnected.complete(i32::MAX),
        Err(Error::NotFound(i32::MAX))
    ));
    assert_eq!(reconnected.create("Next")?.id, 2);
    Ok(())
}
"""Real public CLI/API/PostgreSQL contracts; owns and cleans a unique compose project."""
import datetime as dt
import json
import os
from pathlib import Path
import shutil
import socket
import subprocess
import tempfile
import time
import uuid


def main():
    source = Path(__file__).resolve().parents[1]
    project_name = "todo-test-" + uuid.uuid4().hex[:12]
    with socket.socket() as sock:
        sock.bind(("127.0.0.1", 0))
        port = sock.getsockname()[1]
    env = dict(os.environ, TODO_DB_PORT=str(port))
    url = f"postgres://todo:todo@127.0.0.1:{port}/todo"
    env["DATABASE_URL"] = url
    compose = ["docker", "compose", "-p", project_name, "-f", str(source / "compose.yaml")]

    def docker(*args, capture=False):
        return subprocess.run(compose + list(args), env=env, check=True,
                              capture_output=capture, text=True).stdout

    def sql(query, database="todo"):
        return docker("exec", "-T", "db", "psql", "-U", "todo", "-d", database,
                      "-At", "-v", "ON_ERROR_STOP=1", "-c", query, capture=True).strip()

    try:
        docker("up", "-d", "--wait", "db")
        print(f"Ready: owned compose project {project_name}, port {port}", flush=True)
        with tempfile.TemporaryDirectory(prefix="todo-cli-") as directory:
            root = Path(directory)
            project = root / "project"
            project.mkdir()
            for filename in ("Cargo.toml", "Cargo.lock"):
                shutil.copy2(source / filename, project / filename)
            for folder in ("src", "tests", "examples"):
                shutil.copytree(source / folder, project / folder)
            invocation = root / "invocation"
            invocation.mkdir()
            # A stale JSON file must be ignored, even if malformed.
            storage = project / "tasks.json"
            storage.write_text("unrelated malformed JSON; preserve me")
            cargo = ["cargo", "--offline", "--manifest-path"]
            # Cargo's manifest option belongs to each subcommand.
            def cargo_run(command, *args, database="todo"):
                test_env = dict(env, DATABASE_URL=url.rsplit("/", 1)[0] + "/" + database)
                subprocess.run([cargo[0], command, cargo[1], cargo[2], str(project / "Cargo.toml"),
                                "--target-dir", str(source / "target"), *args],
                               env=test_env, cwd=invocation, check=True)
            sql("CREATE DATABASE api_contract")
            cargo_run("test", database="api_contract")
            sql("CREATE DATABASE example_contract")
            cargo_run("run", "--example", "lifecycle", database="example_contract")
            cargo_run("build")
            binary = source / "target" / "debug" / "todolist_rust"

            def run(args, status=0, contains=None, selected_url=url):
                result = subprocess.run([os.fsencode(binary), *args], cwd=invocation,
                                        env=dict(env, DATABASE_URL=selected_url),
                                        capture_output=True, timeout=12)
                stdout, stderr = result.stdout.decode(), result.stderr.decode()
                assert result.returncode == status, (args, result.returncode, stdout, stderr)
                output = stdout if status == 0 else stderr
                assert not (stderr if status == 0 else stdout), (args, stdout, stderr)
                assert output.strip(), args
                if contains is not None:
                    assert contains in output, (args, output, contains)
                assert storage.read_text() == "unrelated malformed JSON; preserve me"
                assert not (invocation / "tasks.json").exists()
                print(f"{args!r}: exit {status}; {output.strip()!r}", flush=True)
                return stdout

            def rows():
                return json.loads(sql('SELECT coalesce(json_agg(t ORDER BY id), \'[]\') FROM tasks t'))

            def snapshot():
                return (rows(), sql("SELECT last_value, is_called FROM tasks_id_seq"))

            def stamp(value):
                return dt.datetime.fromisoformat(value)

            def changed(before, after, status, earliest):
                for key in ("id", "description", "added"):
                    assert after[key] == before[key], (before, after)
                assert after["status"] == status
                assert stamp(after["update"]) > stamp(before["update"])
                assert earliest <= stamp(after["update"]) <= dt.datetime.now(dt.timezone.utc)

            assert run(["list"]) == "No tasks.\n"
            columns = json.loads(sql("SELECT json_agg(x ORDER BY ordinal_position) FROM (SELECT column_name, data_type, is_nullable, is_identity, ordinal_position FROM information_schema.columns WHERE table_schema='public' AND table_name='tasks') x"))
            assert [(c["column_name"], c["data_type"], c["is_nullable"]) for c in columns] == [
                ("id", "integer", "NO"), ("description", "text", "NO"),
                ("added", "timestamp with time zone", "NO"),
                ("update", "timestamp with time zone", "NO"), ("status", "USER-DEFINED", "NO")]
            assert columns[0]["is_identity"] == "YES"
            assert sql("SELECT string_agg(e.enumlabel, ',' ORDER BY e.enumsortorder) FROM pg_enum e JOIN pg_type t ON t.oid=e.enumtypid WHERE t.typname='task_status'") == "Completed,New,Deleted"
            assert sql("SELECT count(*) FROM pg_constraint WHERE conrelid='tasks'::regclass AND contype='p'") == "1"
            print("Schema:", columns, "enum=Completed,New,Deleted; primary key present", flush=True)
            start = dt.datetime.now(dt.timezone.utc)
            run(["add", "Buy milk"], contains="1")
            run(["add", "-urgent"], contains="2")
            initial = rows()
            assert [(r["id"], r["description"], r["status"]) for r in initial] == [(1, "Buy milk", "New"), (2, "-urgent", "New")]
            for row in initial:
                assert row["added"] == row["update"]
                assert start <= stamp(row["added"]) <= dt.datetime.now(dt.timezone.utc)
            assert run(["list"]) == "1 [ ] Buy milk\n2 [ ] -urgent\n"
            time.sleep(0.02)
            start = dt.datetime.now(dt.timezone.utc)
            run(["complete", "1"], contains="1")
            completed = rows()
            changed(initial[0], completed[0], "Completed", start)
            assert completed[1] == initial[1]
            assert run(["list"]) == "1 [x] Buy milk\n2 [ ] -urgent\n"
            run(["complete", "1"], contains="1")
            assert rows() == completed
            time.sleep(0.02)
            start = dt.datetime.now(dt.timezone.utc)
            run(["delete", "2"], contains="2")
            deleted_b = rows()
            changed(completed[1], deleted_b[1], "Deleted", start)
            assert run(["list"]) == "1 [x] Buy milk\n"
            time.sleep(0.02)
            start = dt.datetime.now(dt.timezone.utc)
            run(["delete", "1"], contains="1")
            changed(completed[0], rows()[0], "Deleted", start)
            assert run(["list"]) == "No tasks.\n"
            for identifier, description in ((3, "C"), (4, ""), (5, "  spaced  "), (6, 'Quoted "café"')):
                run(["add", description], contains=str(identifier))
            assert [(r["id"], r["description"]) for r in rows()[2:]] == [(3, "C"), (4, ""), (5, "  spaced  "), (6, 'Quoted "café"')]
            assert run(["list"]) == '3 [ ] C\n4 [ ] \n5 [ ]   spaced  \n6 [ ] Quoted "café"\n'
            before = snapshot()
            for args in ([], ["help"], ["-h"], ["--help"]):
                output = run(args)
                for phrase in ("add <description>", "delete <id>", "complete <id>", "list", "help", "quote", "PostgreSQL", "DATABASE_URL", "2147483647", "[ ]", "[x]"):
                    assert phrase in output, (args, phrase)
            invalid = [["unknown"], ["--unknown"], ["add"], ["add", "a", "b"], ["list", "extra"], ["help", "extra"], ["-h", "extra"], ["--help", "extra"]]
            for command in ("complete", "delete"):
                invalid.extend([[command], [command, "1", "2"]])
                invalid.extend([[command, value] for value in ("", "-1", "+1", "1a", "1.0", " 1", "١", "2147483648")])
            if os.name == "posix":
                invalid.extend([[b"\xff"], ["add", b"\xff"]])
            for args in invalid:
                run(args, 2, "help")
            for command in ("complete", "delete"):
                for identifier in ("0", "999", "2147483647", "1", "2"):
                    run([command, identifier], 1, "does not exist")
            assert snapshot() == before
            run(["complete", "0003"], contains="3")
            assert rows()[2]["status"] == "Completed"
            before = snapshot()
